                        .filter(vm -> vm.no() == group.getGroupNo()).findFirst().orElseThrow()));
                var data = generation(round.generation()).put("newFiles", round.newFiles()).put("newGroups", round.newGroups())
                        .put("madeListNonEmpty", round.madeListNonEmpty());
