                boolean async = p.has("async") && bool(p, "async");
                for (String path : paths) IpcFiles.input(path);
                importDone = false;
                importFailed = false;
                start(() -> port.commands().importPaths(paths, source, fromDrag));
                if (async) return json.nullNode();
