        // 兼容旧版废弃字段（保留反序列化兼容，仍参与"参数是否统一"判定）
        c.nameLimitStart = nameLimitStart;
        c.nameLimitEnd = nameLimitEnd;
        c.contentLimitStart = contentLimitStart;
        c.contentLimitEnd = contentLimitEnd;
        return c;
    }
